mapper.sql:
(
    EXISTS (
        SELECT 1 FROM user_site_access usa
        WHERE usa.account_id = u.account_id
          AND usa.site_id = #{siteId}
    )
    OR (
        NOT EXISTS (
            SELECT 1 FROM user_site_access usa
            WHERE usa.account_id = u.account_id
        )
        AND u.site_id = #{siteId}
    )
)

mapper.update:
UPDATE user_login_attempt
SET password_error_count = #{passwordErrorCount},
    updated_at = current_timestamp,
    updated_by = #{loginId}, /* login 시도 시에는 user_id 식별불가하여 로그인 시도 ID로 입력 */
    updated_ip = #{updatedIp}
WHERE login_id = #{loginId}

UPDATE user_account
SET account_status = #{accountStatus},
    updated_by = #{updatedBy},
    updated_at = CURRENT_TIMESTAMP,
    updated_ip = #{updatedIp}
WHERE user_id = #{userId}

